import {bootstrap,rpc,fileUrl,identity,uploadBrowserFile,disposeShim} from './host-shim.js';
let disposed=false;
async function sendMedia(value){const entries=Array.isArray(value)?value:[value],ids=[];for(const item of entries){const url=typeof item==='string'?item:item.originalUrl||item.url||item.content;if(!url)throw Error('工具结果没有可用原件');const response=await fetch(url);if(!response.ok)throw Error('读取工具原件失败');const blob=await response.blob(),uploaded=await uploadBrowserFile(new File([blob],item.fileName||item.name||('工具结果-'+crypto.randomUUID()+'.'+(blob.type==='image/svg+xml'?'svg':blob.type.startsWith('video/')?'mp4':'png')),{type:blob.type}));try{const [asset]=await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});ids.push(asset.id);}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}}if(!ids.length)throw Error('没有可发送的工具结果');return rpc('canvas_tool_send',{assets:ids});}
async function sendScript(script){const content=typeof script==='string'?script:JSON.stringify(script,null,2),uploaded=await uploadBrowserFile(new File([content],'剧本-'+crypto.randomUUID()+'.json',{type:'application/json'}));try{const [asset]=await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});return rpc('canvas_tool_send',{text:content});}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}}
async function loadAssets(){return(await rpc('aiyouplus_local_assets',{scope:'all'})).filter(a=>['image','video'].includes(a.kind)).map(a=>({id:a.id,assetId:a.id,type:a.kind,status:'completed',url:fileUrl(a.path),originalUrl:fileUrl(a.path),prompt:'DSH 素材 · '+a.name,timestamp:Date.parse(a.createdAt)||Date.now(),progress:100,width:a.width,height:a.height}));}
const adopted=new Set();async function adoptHistory(history){for(const item of history){if(item.status!=='completed'||!['image','video'].includes(item.type)||!item.url||adopted.has(item.id))continue;adopted.add(item.id);try{const url=item.originalUrl||item.url;if(url.startsWith(location.origin+'/aiyoucodex-dsh/canvas/file'))continue;const response=await fetch(url);if(!response.ok)throw Error('读取结果原件失败');const blob=await response.blob(),uploaded=await uploadBrowserFile(new File([blob],(item.prompt||'创作工具结果').slice(0,60)+'-'+item.id+'.'+(item.type==='video'?'mp4':'png'),{type:blob.type}));try{await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}}catch(error){adopted.delete(item.id);window.dispatchEvent(new CustomEvent('dsh-tools-result-error',{detail:{message:error.message}}));}}}
async function downloadBlob(blob,name){try{if(!blob?.size)throw Error('导出内容为空');const extension=String(name).split('.').pop(),handle=await window.showSaveFilePicker({suggestedName:name,types:[{description:'导出文件',accept:{[blob.type||'application/octet-stream']:['.'+extension]}}]}),writer=await handle.createWritable();await writer.write(blob);await writer.close();const uploaded=await uploadBrowserFile(new File([blob],handle.name,{type:blob.type}));let asset;try{[asset]=await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}return{ok:true,path:asset.path,hint:'已下载并保存到 DSH 统一素材库',filename:handle.name};}catch(error){return{ok:false,error:error.name==='AbortError'?'已取消导出':error.message};}}
async function runEditImage(source,prompt,config,ratio,resolution,options={}){const model=window.__AIYOUPLUS_CANVAS_MODEL_ADAPTER__.getMediaModel(config?.id);if(!model)throw Error('请选择已配置的 DSH 图片模型');const settings=await rpc('aiyouplus_model_config'),profile=settings.profiles?.[model.nativeService],entry=profile?.modelCatalog?.find(row=>row.id===model.modelName&&row.kind==='image');if(!entry||profile.enabled===false)throw Error('图片编辑模型尚未启用');const refs=[source,...(options.refImages||[])],paths=[];async function retain(value,name){let blob;if(value instanceof Blob)blob=value;else if(value instanceof HTMLCanvasElement)blob=await new Promise(resolve=>value.toBlob(resolve,'image/png'));else{const response=await fetch(value);if(!response.ok)throw Error('无法读取编辑原件');blob=await response.blob();}if(!blob?.type.startsWith('image/'))throw Error('编辑参考须为可解码图片');const uploaded=await uploadBrowserFile(new File([blob],name,{type:blob.type}));try{const [asset]=await rpc('aiyouplus_local_import',{inputPaths:[uploaded.path]});return asset.path;}finally{await rpc('canvas_upload_cancel',{uploadId:uploaded.uploadId});}}for(const [index,value]of refs.entries())paths.push(await retain(value,'edit-reference-'+index+'.png'));let maskPath;if(options.markerMasks?.length){if(options.markerMasks.length!==1)throw Error('当前编辑入口一次只支持一个明确蒙版');maskPath=await retain(options.markerMasks[0].mask,'edit-mask.png');}const args={requestId:crypto.randomUUID(),kind:'image',provider:model.nativeService,model:model.modelName,prompt,referencePaths:paths,parameters:{...(entry.parameters||{}),...(options.sourceSettings?.parameters||{}),operation:'edit'},...(maskPath?{maskPath}:{}),...(entry.parameterSchema?.aspectRatio&&ratio&&ratio!=='Auto'?{aspectRatio:ratio}:{}),...(entry.parameterSchema?.resolution&&resolution?{resolution}:{})};options.onProgress?.(5);const result=await rpc('aiyouplus_model_generate',args);if(!result.assets?.length)throw Error('图片编辑 API 未返回已验证入库的真实图片');options.onProgress?.(100);return result.assets.map(asset=>fileUrl(asset.path));}
function notice(message){let node=document.querySelector('[data-dsh-tools-notice]');if(!node){node=document.createElement('p');node.dataset.dshToolsNotice='true';node.setAttribute('role','alert');node.style.cssText='background:#492a28;color:#ffe2de;padding:10px 16px;margin:0';document.body.prepend(node);}node.textContent=message;}
window.addEventListener('dsh-tools-result-error',event=>notice('结果未能进入 DSH 素材库：'+event.detail.message));
window.__DSH_CANVAS__={identity};
window.__DSH_CREATIVE_TOOLS__={sendMedia,sendScript,loadAssets,adoptHistory,downloadBlob,runEditImage,notice,identity,async mountGeneric(host,options){const {mountGenericTool}=await import('./local/generic-tool-workspace.js');return mountGenericTool(host,options);}};
try{await bootstrap();document.body.dataset.dshCreativeTools='true';await import('./local/canvas-model-adapter.js');await import('./assets/canvas.js');await window.__AIYOUPLUS_CANVAS_MODEL_ADAPTER__.refreshModels();document.querySelector('[data-dsh-tools-loading]')?.remove();}catch(error){const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='创作工具载入失败：'+error.message;document.body.append(p);}
document.addEventListener('click',event=>{if(event.target.closest('[aria-label="返回工具"]')){const panel=document.querySelector('[data-dsh-export-panel]');if(panel)panel.hidden=true;}},true);
window.addEventListener('pagehide',()=>{if(disposed)return;disposed=true;window.__AIYOUPLUS_CANVAS_MODEL_ADAPTER__?.dispose();window.__DSH_CANVAS_REACT_ROOT__?.unmount();disposeShim();},{once:true});
